var q = New Query("SELECT TOP 10 Наименование, Цена FROM Catalog.Товары WHERE Цена > &МинЦена ORDER BY Цена DESC");
q.SetParameter("МинЦена", 100);
var res = q.Execute();
var sel = res.Select();
while (sel.Next()) {
    Message(sel.Наименование + ": " + sel.Цена);
}

