// агрегация с группировкой
var q = New Query(
    "SELECT Производитель, SUM(Вес) AS ОбщийВес " +
    "FROM Catalog.Товары GROUP BY Производитель HAVING SUM(Вес) > 50");
var sel = q.Execute().Select();
while (sel.Next())
    Message(sel.Производитель + " -> " + sel.ОбщийВес);

